<?php

declare(strict_types=1);

namespace Tests\Unit;

use Codeception\Test\Unit;
use Db\Enum\IssuePriority;
use Db\Row\IssueRow;
use Db\Row\IssueStatusRow;
use Db\RowShapeException;

/**
 * Hermetic unit tests for row classes generated by tools/generate-row-classes.php.
 * Rows are the shape PDO::FETCH_ASSOC returns with emulated prepares off.
 */
final class GeneratedRowsTest extends Unit
{
    /**
     * @param array<string, mixed> $overrides
     * @return array<string, mixed>
     */
    private function issueRow(array $overrides = []): array
    {
        return array_merge([
            'issue_id'        => 511,
            'priority'        => 'high',
            'project_id'      => 1,
            'parent_issue_id' => null,
            'author_aiu'      => 35,
            'assignee_aiu'    => 35,
            'status_id'       => 1,
            'title'           => 'Typed issues',
            'description'     => null,
            'created_at_utc'  => '2026-09-15 12:00:00.123456',
            'updated_at_utc'  => '2026-09-15 12:30:00.000001',
            'done_at_utc'     => null,
        ], $overrides);
    }

    public function testIssueRowHydratesTypedProperties(): void
    {
        $issue = IssueRow::fromRow($this->issueRow());

        $this->assertSame(511, $issue->issueId);
        $this->assertSame(IssuePriority::High, $issue->priority);
        $this->assertNull($issue->parentIssueId);
        $this->assertSame(35, $issue->assigneeAiu);
        $this->assertSame('Typed issues', $issue->title);
        $this->assertNull($issue->description);
        $this->assertSame('2026-09-15 12:00:00.123456', $issue->createdAtUtc->format('Y-m-d H:i:s.u'));
        $this->assertNull($issue->doneAtUtc);
    }

    public function testIssueRowIgnoresExtraJoinedColumns(): void
    {
        $issue = IssueRow::fromRow($this->issueRow(['status_slug' => 'open', 'can_write' => 1]));

        $this->assertSame(511, $issue->issueId);
    }

    public function testIssueRowRejectsAnUnknownPriority(): void
    {
        $this->expectException(RowShapeException::class);
        IssueRow::fromRow($this->issueRow(['priority' => 'urgent']));
    }

    public function testIssueRowRejectsAMissingColumn(): void
    {
        $row = $this->issueRow();
        unset($row['title']);

        $this->expectException(RowShapeException::class);
        IssueRow::fromRow($row);
    }

    public function testIssueRowJsonMatchesTheApiRowShape(): void
    {
        $this->assertSame(
            '{"issue_id":511,"priority":"high","project_id":1,"parent_issue_id":null,'
            . '"author_aiu":35,"assignee_aiu":35,"status_id":1,"title":"Typed issues",'
            . '"description":null,"created_at_utc":"2026-09-15 12:00:00.123456",'
            . '"updated_at_utc":"2026-09-15 12:30:00.000001","done_at_utc":null}',
            json_encode(IssueRow::fromRow($this->issueRow()), JSON_THROW_ON_ERROR),
        );
    }

    public function testIssueStatusFlagsAreBoolsThatStillSerializeAsZeroOrOne(): void
    {
        $status = IssueStatusRow::fromRow([
            'status_id'      => 4,
            'slug'           => 'done',
            'label'          => 'Done',
            'sort_order'     => 40,
            'is_terminal'    => 1,
            'is_default'     => 0,
            'created_at_utc' => '2026-04-20 04:42:40.557849',
        ]);

        $this->assertTrue($status->isTerminal);
        $this->assertFalse($status->isDefault);
        $this->assertSame(
            '{"status_id":4,"slug":"done","label":"Done","sort_order":40,"is_terminal":1,'
            . '"is_default":0,"created_at_utc":"2026-04-20 04:42:40.557849"}',
            json_encode($status, JSON_THROW_ON_ERROR),
        );
    }
}
